head.script:
scwin.__isInteger = function() {
    var num = +(WebSquare.wUnit.getObjById('gridView1_column11').innerText.replace(',', ''));
    return num == 50100.94;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. Property 탭 또는 Source 탭에서 column11 의 expression 부분을 확인한다.
    //1. In the Property tab or Source tab, check the expression part of column11.
    // verify step 1. expression="SUM("col2")"
    //1. expression = "SUM ("col2")"
    // Test step 2. column11 의 dataType 부분을 확인한다.
    //2. Check the dataType part of column11.
    // verify step 2. dataType="number" 
    //2. dataType = "number"
    // Test step 3. displayFormat 부분을 확인한다.
    //3. Check the displayFormat section.
    // verify step 3. displayFormat="#,##0.00"
    //3. displayFormat = "#, ## 0.00"
    // Test step 4. 브라우저에서 Footer 부분을 확인한다.
    //4. Check the Footer section in your browser.
    // verify step 4. 정확하게 소수점까지 계산된다. (그전버전에서는 그림1처럼 정수로 올림되는 현상이 발생함)
    //4. Accurate to the decimal point. (In previous versions, the result is raised to an integer as shown in Figure 1.)
    WebSquare.wUnit.addCommand("assert", "scwin.__isInteger()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
